    public sealed record checkpoint_managerConfig
    {
        public string NodeId { get; init; } = "checkpoint_manager_node_0";
        public int MaxIterations { get; init; } = 1000;
        public double LearningRate { get; init; } = 0.001;
        public double EWCLambda { get; init; } = 400.0;
        public int ReplayBufferSize { get; init; } = 1024;
        public int BatchSize { get; init; } = 32;
        public double AnchorAlpha { get; init; } = 0.5;
        public int HammingThreshold { get; init; } = 24;
        public int MaxClusters { get; init; } = 64;
        public double GradientClipNorm { get; init; } = 5.0;
        public bool EnableDifferentialPrivacy { get; init; } = true;
        public double DPEpsilon { get; init; } = 0.1;
        public double DPDelta { get; init; } = 1e-5;
        public int Seed { get; init; } = 42;
        public string CheckpointDir { get; init; } = "checkpoints/checkpoint_manager";
        public int FisherSamples { get; init; } = 200;
        public double QuantumCoherence { get; init; } = 0.99;
        public int NQuantumUnits { get; init; } = 300;
    }

